// Minimal original-paper identifiers for an already selected independent audit.
package main
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"io";"os";"sort";"sync";"time";"github.com/parquet-go/parquet-go")
type request struct{ID uint64 `json:"id"`;Year int32 `json:"year"`;Type string `json:"type"`;XPAC bool `json:"is_xpac"`;Path string `json:"raw_path"`;Row int64 `json:"raw_row_index"`}
type row struct{ID *string `parquet:"id"`;Year *int32 `parquet:"publication_year"`;Type *string `parquet:"type"`;XPAC *bool `parquet:"is_xpac"`;Title *string `parquet:"display_name"`;DOI *string `parquet:"doi"`;IDs map[string]*string `parquet:"ids"`}
type result struct{request;Title string `json:"title"`;DOI string `json:"doi"`;IDs map[string]string `json:"ids"`;OriginalIdentityVerified bool `json:"original_identity_verified"`}
func must(e error){if e!=nil{panic(e)}}
func val(s *string)string{if s==nil{return ""};return *s}
func main(){if len(os.Args)!=3{panic("usage: paper_lookup requests.json output.json")};start:=time.Now();b,e:=os.ReadFile(os.Args[1]);must(e);sh:=sha256.Sum256(b);var in struct{Works []request `json:"works"`};must(json.Unmarshal(b,&in));groups:=map[string][]request{};for _,r:=range in.Works{groups[r.Path]=append(groups[r.Path],r)}
 paths:=[]string{};for p:=range groups{paths=append(paths,p)};sort.Strings(paths);jobs:=make(chan string);done:=make(chan []result);var wg sync.WaitGroup
 for i:=0;i<4;i++{wg.Add(1);go func(){defer wg.Done();for p:=range jobs{rs:=groups[p];sort.Slice(rs,func(i,j int)bool{return rs[i].Row<rs[j].Row});f,e:=os.Open(p);must(e);st,e:=f.Stat();must(e);pf,e:=parquet.OpenFile(f,st.Size(),parquet.SkipPageIndex(true),parquet.SkipBloomFilters(true));must(e);r:=parquet.NewGenericReader[row](pf);buf:=make([]row,1);out:=[]result{}
  for _,q:=range rs{must(r.SeekToRow(q.Row));n,e:=r.Read(buf);if e!=nil&&e!=io.EOF{panic(e)};if n!=1{panic("missing source row")};x:=buf[0];if val(x.ID)!=fmt.Sprintf("https://openalex.org/W%d",q.ID)||x.Year==nil||*x.Year!=q.Year||val(x.Type)!=q.Type||(x.XPAC!=nil&&*x.XPAC)!=q.XPAC{panic("source identity mismatch")};y:=result{request:q,Title:val(x.Title),DOI:val(x.DOI),IDs:map[string]string{},OriginalIdentityVerified:true};for k,v:=range x.IDs{y.IDs[k]=val(v)};out=append(out,y)};must(r.Close());must(f.Close());done<-out
 }}()};go func(){for _,p:=range paths{jobs<-p};close(jobs);wg.Wait();close(done)}();all:=[]result{};for rs:=range done{all=append(all,rs...)};if len(all)!=len(in.Works){panic("count mismatch")};sort.Slice(all,func(i,j int)bool{return all[i].ID<all[j].ID});v:=map[string]any{"status":"minimal_original_identifiers_verified","request_sha256":hex.EncodeToString(sh[:]),"works":all,"rows":len(all),"source_parts":len(groups),"workers":4,"elapsed_seconds":time.Since(start).Seconds(),"production_mutated":false};b,e=json.MarshalIndent(v,"","  ");must(e);must(os.WriteFile(os.Args[2],append(b,'\n'),0600));fmt.Printf("rows=%d parts=%d seconds=%.2f\n",len(all),len(groups),time.Since(start).Seconds())}
